import type * as ReactNS from "react";

import { useT } from "../i18n";
import { WbTooltip } from "./WbTooltip";

const host = window.QwenPaw.host;
const React: typeof ReactNS = host.React;
const antd = host.antd;

// 纯触屏（无 hover 概念）——代码块复制按钮常显，否则 hover 才显 = 触屏不可达
const IS_TOUCH =
  typeof window !== "undefined" &&
  !!window.matchMedia &&
  window.matchMedia("(hover: none)").matches;

/** ：
 * Element/Matrix 口径——消息 body 里的整 MXID（@local:server[:port]）被
 * 正则扫描渲染成 pill（Element Pill.tsx 同款前端后处理；本集群
 * formatted_body 不含 matrix.to 链接，纯前端正则即正解）。chip 显
 * localpart（Element pill 显示 displayname 的同位），Tooltip 给整 MXID，
 * 点击 = onMentionClick(整 MXID)。短 @name（无 :server）保留旧高亮。
 * 正则对齐 Matrix MXID 规范：localpart 允许 a-z0-9._=+/-，server 允许
 * a-z0-9.- 与可选 :port。 */
/** 整 MXID 判型（无 g——.test 无 lastIndex 状态坑；全锚定）。 */
const MXID_TEST = /^@[a-z0-9._=+-]+:[a-z0-9.-]+(?::\d+)?$/i;

function MentionPill({
  mxid,
  onMentionClick,
}: {
  mxid: string;
  onMentionClick?: (mxid: string) => void;
}) {
  const localpart = mxid.split(":")[0].replace(/^@/, "");
  return (
    <WbTooltip title={mxid} mouseEnterDelay={0.3} tap={false} >
      <span
        onClick={onMentionClick ? () => onMentionClick(mxid) : undefined}
        style={{
          display: "inline-block",
          maxWidth: "100%",
          padding: "0 6px",
          margin: "0 1px",
          borderRadius: 999,
 background: "color-mix(in srgb, var(--app-accent, #FF7F16) 12%, transparent)",
 border: "1px solid color-mix(in srgb, var(--app-accent, #FF7F16) 35%, transparent)",
          color: "var(--app-accent, #d46b08)",
          fontWeight: 600,
          fontSize: "0.92em",
          lineHeight: "1.6em",
          cursor: onMentionClick ? "pointer" : undefined,
          whiteSpace: "nowrap",
          overflowWrap: "anywhere",
          // 竖屏溢出修复：nowrap 单行 pill 无宽度上限时长 MXID 会撑破气泡
          // 右边界——封顶容器宽 + 省略号（完整 MXID 已在上方 Tooltip）；
          // 放不下剩余行宽时整颗 pill 原子换行。宽屏普通名 < 容器宽，
          // 以上属性不生效 = 零变化。
          boxSizing: "border-box",
          overflow: "hidden",
          textOverflow: "ellipsis",
        }}
      >
        @{localpart}
      </span>
    </WbTooltip>
  );
}

/** 行内格式：`code` / **bold** / *italic* / @mention（整 MXID pill + 短名）/ 裸 URL。
 * memo——blocks 缓存命中时（已完成消息）
 * 父行重渲染不再重跑逐 token 正则 + 节点重建（流式期成本点）。 */
const InlineMd = React.memo(function InlineMd({
  text,
  onMentionClick,
}: {
  text: string;
  onMentionClick?: (name: string) => void;
}) {
  const nodes: ReactNS.ReactNode[] = [];
  const regex =
    /(`[^`\n]+`|\*\*[^*\n]+\*\*|\*[^*\n]+\*|@[a-z0-9._=+-]+:[a-z0-9.-]+(?::\d+)?|@[\w\u4e00-\u9fa5-]+|https?:\/\/[^\s]+)/gi;
  let last = 0;
  let m: RegExpExecArray | null;
  let key = 0;
  while ((m = regex.exec(text)) !== null) {
    if (m.index > last) nodes.push(text.slice(last, m.index));
    const tok = m[0];
    if (tok.startsWith("`") && tok.endsWith("`")) {
      nodes.push(
        <code
          key={key++}
          style={{
            background: "rgba(0,0,0,0.06)",
            borderRadius: 4,
            padding: "1px 5px",
            fontSize: 13,
            fontFamily: "monospace",
            // 超长单行行内码（URL/token）强制换行，不撑宽气泡。
            overflowWrap: "anywhere",
            wordBreak: "break-all",
          }}
        >
          {tok.slice(1, -1)}
        </code>,
      );
    } else if (tok.startsWith("**") && tok.endsWith("**")) {
      nodes.push(<b key={key++}>{tok.slice(2, -2)}</b>);
    } else if (tok.startsWith("*") && tok.endsWith("*") && tok.length > 2) {
      nodes.push(<i key={key++}>{tok.slice(1, -1)}</i>);
    } else if (tok.startsWith("@")) {
      // 13.8：整 MXID 与短 @name **统一 pill**（此前短名只是橙色
      // 加粗——@mention 是简单字符串）。MentionPill 对无 :server 的
      // 短名同样工作（chip=localpart，Tooltip=短名，点击=onMentionClick 短名
      // 插入输入框走原逻辑）。
      if (MXID_TEST.test(tok)) {
        nodes.push(
          <MentionPill key={key++} mxid={tok} onMentionClick={onMentionClick} />,
        );
      } else {
        nodes.push(
          <MentionPill
            key={key++}
            mxid={tok}
            onMentionClick={onMentionClick ? () => onMentionClick(tok.slice(1)) : undefined}
          />,
        );
      }
    } else {
      nodes.push(
        <a
          key={key++}
          href={tok}
          target="_blank"
          rel="noreferrer"
          style={{ color: "#1677ff" }}
        >
          {tok}
        </a>,
      );
    }
    last = m.index + tok.length;
  }
  if (last < text.length) nodes.push(text.slice(last));
  return <>{nodes}</>;
});

/** 复制按钮（代码块用）。 */
function CopyButton({ text }: { text: string }) {
  const tr = useT();
  const [copied, setCopied] = React.useState(false);
  return (
    <antd.Button
      type="text"
      size="small"
      style={{ color: "#bbb", fontSize: 11 }}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          window.setTimeout(() => setCopied(false), 1500);
        } catch {
          /* clipboard 不可用 */
        }
      }}
    >
      {copied ? tr("已复制") : tr("复制")}
    </antd.Button>
  );
}

/** 代码块：深底 + 语言标签 + 复制。 */
/** （13.6 「看看 dashboard 和 QwenPaw 怎么渲染消息，
 * 继续优化」）：代码块对齐 dashboard markdown-message CodeBlock 口径——
 * 浅底卡片 + 边框 + 灰底语言栏 + 复制按钮**hover 才出现**（dashboard
 * opacity-0 group-hover:opacity-100 同款），替代 13.6 的暗色底+常显复制
 * （聊天流里暗块太跳、常显按钮干扰阅读）。 */
function CodeBlock({ code, lang }: { code: string; lang: string }) {
  const [hover, setHover] = React.useState(false);
  return (
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        border: "1px solid rgba(127,127,127,0.25)",
        background: "rgba(127,127,127,0.08)",
        borderRadius: 8,
        margin: "6px 0",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "2px 8px",
          fontSize: 11,
          color: "rgba(127,127,127,0.9)",
          background: "rgba(127,127,127,0.12)",
        }}
      >
        <span>{lang || "code"}</span>
        <span
          style={{
            opacity: hover || IS_TOUCH ? 1 : 0,
            transition: "opacity 0.15s",
            display: "inline-flex",
          }}
        >
          <CopyButton text={code} />
        </span>
      </div>
      <pre
        style={{
          margin: 0,
          padding: "8px 12px",
          overflowX: "auto",
          fontSize: 12,
          lineHeight: 1.55,
          fontFamily: "ui-monospace, SFMono-Regular, Consolas, monospace",
        }}
      >
        <code>{code}</code>
      </pre>
    </div>
  );
}

/** 块级结构：代码块 / 标题 / 列表（有序/无序）/ 表格 / 引用 / 普通段。 */
interface Block {
  type: "code" | "h" | "list" | "table" | "quote" | "text";
  lang?: string;
  content: string;
  items?: string[];
  /** 表格：行数组（首行 = 表头）。。 */
  rows?: string[][];
  /** 有序列表标记。。 */
  ordered?: boolean;
  /** 标题层级（1-6）。。 */
  level?: number;
}

/** 表格分隔行：|---|:---:|---| （只含 | - : 空格且至少一个 -）。 */
function isTableSep(line: string): boolean {
  if (!line.includes("-")) return false;
  return /^\s*\|?[\s:|-]+\|?\s*$/.test(line) && line.includes("|");
}

/** 表格行 → 单元格数组（去首尾 | 后按 | 切分，逐格 trim）。 */
function splitTableRow(line: string): string[] {
  let s = line.trim();
  if (s.startsWith("|")) s = s.slice(1);
  if (s.endsWith("|")) s = s.slice(0, -1);
  return s.split("|").map((c) => c.trim());
}

function parseBlocks(text: string): Block[] {
  const blocks: Block[] = [];
  const lines = text.split("\n");
  let i = 0;
  let buf: string[] = [];
  const flush = () => {
    if (buf.length) {
      blocks.push({ type: "text", content: buf.join("\n") });
      buf = [];
    }
  };
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim().startsWith("```")) {
      flush();
      const lang = line.trim().slice(3).trim();
      const code: string[] = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith("```")) {
        code.push(lines[i]);
        i++;
      }
      i++; // 跳过结束 ```
      blocks.push({ type: "code", lang, content: code.join("\n") });
      continue;
    }
    const hMatch = /^#{1,6}\s+/.exec(line);
    if (hMatch) {
      flush();
      blocks.push({
        type: "h",
        level: hMatch[0].trim().length, // "## " → 3（# 数 + 1）
        content: line.replace(/^#{1,6}\s+/, "").trim(),
      });
      i++;
      continue;
    }
    // 表格（）：| 开头行 + 下一行是分隔行 |---|---| → 吃掉连续 | 行。
    // 报告类产物（对比表/清单）表格是主形态——此前全部按 RAW 文本渲染，
    // 用户「md 预览 RAW 没修好」的主要根因之一。
    if (
      /^\s*\|/.test(line) &&
      i + 1 < lines.length &&
      isTableSep(lines[i + 1])
    ) {
      flush();
      const rows: string[][] = [splitTableRow(line)];
      i += 2; // 跳过表头 + 分隔行
      while (i < lines.length && /^\s*\|/.test(lines[i])) {
        rows.push(splitTableRow(lines[i]));
        i++;
      }
      blocks.push({ type: "table", content: "", rows });
      continue;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      flush();
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, "").trim());
        i++;
      }
      blocks.push({ type: "list", content: "", items });
      continue;
    }
    if (/^\s*\d+[.)]\s+/.test(line)) {
      // 有序列表（）：1. / 2) 连续行。
      flush();
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+[.)]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+[.)]\s+/, "").trim());
        i++;
      }
      blocks.push({ type: "list", content: "", items, ordered: true });
      continue;
    }
    if (/^\s*>\s?/.test(line)) {
      flush();
      const qs: string[] = [];
      while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
        qs.push(lines[i].replace(/^\s*>\s?/, ""));
        i++;
      }
      blocks.push({ type: "quote", content: qs.join("\n") });
      continue;
    }
    buf.push(line);
    i++;
  }
  flush();
  return blocks;
}

interface MdTextProps {
  text: string;
  /** 折叠阈值（字符数）；超长文本默认折叠显示前 400 字符。 */
  maxLength?: number;
  onMentionClick?: (name: string) => void;
}

/** 零依赖 markdown 渲染：代码块/标题/列表/引用 + 行内格式 + @高亮 + 长文折叠。
 * memo——text 未变的行（流式期间已完成的
 * 历史消息）父行重渲染时整体跳过（parseBlocks + 块 JSX + InlineMd 全不跑）。 */
export default React.memo(function MdText({
  text,
  maxLength = 800,
  onMentionClick,
}: MdTextProps) {
  const tr = useT();
  const [expanded, setExpanded] = React.useState(false);
  const isLong = text.length > maxLength;
  const shown = isLong && !expanded ? text.slice(0, 400) : text;
  const blocks = React.useMemo(() => parseBlocks(shown), [shown]);

  return (
    <div style={{ whiteSpace: "normal", wordBreak: "break-word" }}>
      {blocks.map((b, bi) => {
        switch (b.type) {
          case "code":
            return <CodeBlock key={bi} code={b.content} lang={b.lang || ""} />;
          case "h": {
            const lvl = b.level || 3;
            const fontSize = lvl <= 1 ? 17 : lvl <= 2 ? 16 : lvl <= 4 ? 15 : 13.5;
            return (
              <div
                key={bi}
                style={{ fontWeight: 700, fontSize, margin: "6px 0 2px" }}
              >
                <InlineMd text={b.content} onMentionClick={onMentionClick} />
              </div>
            );
          }
          case "list":
            const listStyle = { margin: "4px 0", paddingLeft: 22 } as const;
            return b.ordered ? (
              <ol key={bi} style={listStyle}>
                {(b.items || []).map((it, ii) => (
                  <li key={ii} style={{ margin: "2px 0" }}>
                    <InlineMd text={it} onMentionClick={onMentionClick} />
                  </li>
                ))}
              </ol>
            ) : (
              <ul key={bi} style={listStyle}>
                {(b.items || []).map((it, ii) => (
                  <li key={ii} style={{ margin: "2px 0" }}>
                    <InlineMd text={it} onMentionClick={onMentionClick} />
                  </li>
                ))}
              </ul>
            );
          case "table": {
            const cellBorder = "1px solid rgba(127,127,127,0.28)";
            const cols = (b.rows && b.rows[0] ? b.rows[0].length : 1) || 1;
            return (
              <div key={bi} style={{ overflowX: "auto", margin: "6px 0" }}>
                <table
                  style={{
                    borderCollapse: "collapse",
                    width: "100%",
                    fontSize: 12.5,
                    lineHeight: 1.5,
                  }}
                >
                  <thead>
                    <tr>
                      {(b.rows?.[0] || Array.from({ length: cols }, () => ""))
                        .slice(0, cols)
                        .map((c, ci) => (
                          <th
                            key={ci}
                            style={{
                              border: cellBorder,
                              padding: "4px 10px",
                              background: "rgba(0,0,0,0.045)",
                              textAlign: "left",
                              fontWeight: 600,
                              whiteSpace: "nowrap",
                            }}
                          >
                            {c}
                          </th>
                        ))}
                    </tr>
                  </thead>
                  <tbody>
                    {(b.rows || []).slice(1).map((row, ri) => (
                      <tr key={ri}>
                        {Array.from({ length: cols }, (_, ci) => (
                          <td
                            key={ci}
                            style={{
                              border: cellBorder,
                              padding: "4px 10px",
                              wordBreak: "break-word",
                              verticalAlign: "top",
                            }}
                          >
                            <InlineMd
                              text={row[ci] ?? ""}
                              onMentionClick={onMentionClick}
                            />
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          }
          case "quote":
            return (
              <div
                key={bi}
                style={{
                  borderLeft: "3px solid rgba(0,0,0,0.2)",
                  paddingLeft: 10,
                  color: "#888",
                  fontSize: 13,
                  margin: "4px 0",
                }}
              >
                <InlineMd text={b.content} onMentionClick={onMentionClick} />
              </div>
            );
          default:
            return (
              <div key={bi} style={{ margin: "2px 0" }}>
                <InlineMd text={b.content} onMentionClick={onMentionClick} />
              </div>
            );
        }
      })}
      {isLong ? (
        <antd.Button
          type="link"
          size="small"
          style={{ padding: 0, fontSize: 12 }}
          onClick={() => setExpanded((v) => !v)}
        >
          {expanded ? tr("收起") + " ↑" : tr("展开全文（{kb} KB）↓", { kb: Math.round(text.length / 1024) })}
        </antd.Button>
      ) : null}
    </div>
  );
});
