// P6（管理页重构）：原单体 OpsPanel 拆导出——OpsOverview（集群状态/版本
// + 集群负载 SGLang）与 OpsLogPane（组件日志）供「管理」页集群管理域分用
// （概览=中栏、日志=二级页，升级卡归 Worker 详情不在此）。10/29 顶层
// 「运维」「审计」tab 已下线；15.35 default 组合 OpsPanel 退役（升级卡
// 已单 worker 化进 Worker 详情，零引用者）——本文件仅余两个命名导出。
// 轮询门 = useTabActive("ops") || active（宿主显式激活，旧 tab 已下线恒
// false——与 RuntimeUpgradePanel 同款 active-prop 模式）。

const host = window.QwenPaw.host;
const React = host.React;
const antd = host.antd;
const icons = (host.antdIcons || {}) as Record<string, ReactNS.ComponentType>;
const EmptyIcon = (() => null) as unknown as ReactNS.FC<Record<string, unknown>>;
const pick = (name: string): ReactNS.FC<Record<string, unknown>> =>
  (icons[name] as ReactNS.FC<Record<string, unknown>>) || EmptyIcon;
const ReloadIcon = pick("ReloadOutlined");

/** 集群状态（Controller /api/v1/status，L1 admin token）。 */
interface ClusterStatus {
  [k: string]: unknown;
}

interface LogLine {
  timestamp: string;
  level: "info" | "error";
  component: string;
  message: string;
}

/** Docker 日志时间戳（UTC ISO，如 2026-08-14T03:22:11.123Z）→ 本地 MM-DD HH:MM:SS。
 此前 slice(11,19) 显示 UTC 裸时分秒（比本地慢 8 小时且无日期）——
 「日志时间看不清是哪天」，加日期+转本地。解析失败回退原 slice。 */
/** 集群版本卡（AgentTeams / Higress，与状态卡同款式）。 */
function VersionStatCard({
  label,
  value,
  sub,
  t,
}: {
  label: string;
  value?: string | null;
  sub?: string | null;
  t: { border: string; cardBg: string; textSecondary: string };
}) {
  return (
    <div
      style={{
        padding: "10px 12px",
        borderRadius: 8,
        border: `1px solid ${t.border}`,
        background: t.cardBg,
      }}
    >
      <div style={{ fontSize: 11, color: t.textSecondary }}>{label}</div>
      <div
        style={{
          fontSize: 13,
          fontWeight: 600,
          overflow: "hidden",
          textOverflow: "ellipsis",
          whiteSpace: "nowrap",
        }}
        title={value || "—"}
      >
        {value || "—"}
        {sub ? (
          <span
            style={{
              fontSize: 10,
              fontWeight: 400,
              color: t.textSecondary,
              marginLeft: 6,
            }}
          >
            {sub}
          </span>
        ) : null}
      </div>
    </div>
  );
}

function fmtLogTime(ts: string): string {
  const d = new Date(ts);
  if (isNaN(d.getTime())) return ts.slice(11, 19);
  const p = (x: number) => String(x).padStart(2, "0");
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(
    d.getMinutes(),
  )}:${p(d.getSeconds())}`;
}

const COMPONENTS = [
  { value: "controller", label: "Controller" },
  { value: "manager", label: "Manager" },
  { value: "matrix", label: "Matrix（控制器内）" },
  { value: "higress", label: "Higress（控制器内）" },
  { value: "minio", label: "MinIO（控制器内）" },
];

/**
 * OpsOverview——运维概览卡组（集群状态/版本 + 集群负载 SGLang）。
 * P6 自单体 OpsPanel 拆出，供集群管理域中栏（不含运行时升级——升级卡归
 * Worker 详情）；组件日志区见 OpsLogPane。
 * active=宿主显式激活（10/29 顶层「运维」tab 下线 → 旧 useTabActive("ops")
 * 恒 false，不显式传则轮询停摆）。
 */
export function OpsOverview({
  refreshTick = 0,
  active = false,
}: {
  refreshTick?: number;
  active?: boolean;
}) {
  const t = useThemeColors();
  const tr = useT();
  const [status, setStatus] = React.useState<ClusterStatus | null>(null);
  const [statusLoading, setStatusLoading] = React.useState(false);
  // 集群版本（/cluster-info：AgentTeams=controller 镜像 tag，
  // Higress=三级源探测）。后端 10min 缓存 → 前端仅挂载 + 手动刷新时取，
  // 不进 1s 轮询（慢变事实，不打无谓请求）。
  const [clusterInfo, setClusterInfo] = React.useState<{
    agentteams_version?: string | null;
    higress_version?: string | null;
    higress_version_source?: string | null;
    higress_version_error?: string;
  } | null>(null);

  const refreshStatus = React.useCallback(async () => {
    setStatusLoading(true);
    try {
      const data = (await requestJson(
        "/agentteams-proxy/controller/api/v1/status",
      )) as ClusterStatus;
      setStatus(data);
    } catch (e) {
      antd.message.error(
        e instanceof Error ? e.message : tr("集群状态获取失败"),
      );
    } finally {
      setStatusLoading(false);
    }
  }, []);

  // 集群版本取数：失败静默降级（版本卡显 "—"）——不弹错打扰
  // 主状态视图（版本是附加信息，不该阻断集群状态）。
  const refreshClusterInfo = React.useCallback(async () => {
    try {
      const data = (await requestJson(
        "/agentteams-proxy/cluster-info",
      )) as NonNullable<typeof clusterInfo>;
      setClusterInfo(data);
    } catch {
      /* 降级空态（后端 403/探测失败字段 null） */
    }
  }, []);

  // 模型网关路由目录卡已移除（重复视图——模型页
  // ModelsTab 已有「模型网关配置」功能超集），关联 state/fetch 一并清理。

  // 活跃 tab 单源（rc-tabs 保活，切走仍需显式
  // 门控——ops 的 1s 集群负载轮询此前切走常驻）。
  // 布尔快照——非 ops tab 互切不再重渲
  // 本面板（连点 Tab 固定成本）。
  // P6：|| active——顶层「运维」tab 下线后旧门恒 false，宿主
  // （集群管理域中栏）显式传激活，轮询才续。
  const opsActive = useTabActive("ops") || active;

  // 可选模块：集群负载（L1 专属）。未启用时后端 404 → sglangOff=true 不渲染卡片。
  const [sglang, setSglang] = React.useState<SglangLoads | null>(null);
  const [sglangOff, setSglangOff] = React.useState(false);
  const [sglangLoading, setSglangLoading] = React.useState(false);
  const [sglangError, setSglangError] = React.useState("");

  // silent=true：后台轮询不闪 loading（手动刷新按钮走非 silent）。
  // 刷新感知（14.34）：最后成功轮询时刻——每轮必刷（独立于
  // setSglang 的 diff 门，空闲数值不变时也跳）。作脉冲点 remount
  // key：每来一帧绿点 ping 一次。（14.33「快照 N 秒前」age 在 1s
  // 轮询下恒显 0、无可感知性，用户点名删——改脉冲点。）
  const [sglangLocalAt, setSglangLocalAt] = React.useState<number>(0);
  // 稳定快照（refreshSglang
  // deps=[]，不能直接读 state；ref 每次渲染同步最新值）。
  const sglangRef = React.useRef(sglang);
  sglangRef.current = sglang;
  // ── 自适应节奏（SGLang 卡片刷新回归的系统修复）──────────────────
  // 业界监控采集通式（Prometheus scrape tuning / nvidia-smi dmon）：
  // 活跃采样快、空闲采样稀。14.17 一刀切 1s→5s 导致验收实测回归「刷新
  // 很慢几乎不刷」——改两档：数据指纹变（推理中）=1s 快档（恢复 1s 时代
  // 实时感）；连续 2 周期不变（空闲）=慢档。
  // 慢档 15s→5s——14.26 批
  // 把「15s 一帧」归因到 SGLang 参数 load_snapshot_publish_interval=15，
  // 实查该参数单位是 **decode 迭代次数**（非秒）且 prefill/停滞/空闲均
  // 强制即时发布，忙态实测快照 ≥1Hz、陈旧度 <1s（192 报告 §2.3）——
  // 用户感知「15s 才跳」的真凶是本慢档本身。5s 档=负载恢复时最迟 5s
  // 内回快档，带宽代价每 5s 数 KB（5M 行可忽略）。
  const SG_FAST_MS = 1000;
  const SG_SLOW_MS = 5000;
  const sgCadenceRef = React.useRef(SG_FAST_MS);
  const sgStableRef = React.useRef(0);
  const sgFingerprint = (d: SglangLoads | null): string =>
    d ? JSON.stringify({ ...d, timestamp: "" }) : "";
  // ── KV 活信号（自采样）──────────────────────
  // gen_throughput 是 SGLang 侧「decode 窗口采样」：只在 decode-stats
  // tick 计算，连续 30s 无 decode（长 prefill/采样稀疏）即归零导出——
  // 推理在跑（KV 仍在变化）时卡片也可能显示 0.0 tok/s。活信号改由
  // 前端自采样：相邻两次 poll 的 num_used_tokens 变化 = KV 在动。
  // 两信号并显（吞吐=采样窗速率 / 活动=实时占用变化），不再单值误导。
  const sgKvPrevRef = React.useRef<Map<number, number>>(new Map());
  const sgKvMovingRef = React.useRef<Set<number>>(new Set());
  const refreshSglang = React.useCallback(async (silent = false) => {
    if (!silent) setSglangLoading(true);
    try {
      const data = await fetchSglangLoads();
      // 活信号采样：占用变化必然改指纹 → 本轮 setSglang 重渲染，
      // 渲染时读 sgKvMovingRef 即最新值（idle 轮 moved=空，无渲染亦无感）。
      const prevMap = sgKvPrevRef.current;
      const moved = sgKvMovingRef.current;
      moved.clear();
      for (const r of data.ranks) {
        const prev = prevMap.get(r.dp_rank);
        if (prev !== undefined && r.num_used_tokens !== prev) moved.add(r.dp_rank);
        prevMap.set(r.dp_rank, r.num_used_tokens);
      }
      const changed =
        sgFingerprint(sglangRef.current) !== sgFingerprint(data);
      if (changed) {
        setSglang(data);
        sgStableRef.current = 0;
        sgCadenceRef.current = SG_FAST_MS;
      } else {
        // 连续 2 周期不变才降速（一周期确认，防快变场景误判空闲）。
        sgStableRef.current += 1;
        if (sgStableRef.current >= 2) sgCadenceRef.current = SG_SLOW_MS;
      }
      // 「更新于」=最后检查时间（监控卡活性证明，每检查必跳）——
      // 14.19 初版 diff 门把它绑成"最后变化时间"，空闲时停摆=假死观感
      // （回归反馈真根因之一）。
      // 脉冲点每轮必刷（独立于 setSglang 的 diff 门——空闲数值
      // 不变时也 ping，刷新可感知）。
      setSglangLocalAt(Date.now());
      setSglangOff(false);
      setSglangError("");
    } catch (e) {
      if (e instanceof Error && e.message.includes("HTTP 404")) {
        setSglangOff(true); // 模块未启用——不显示卡片
      } else {
        setSglangError(e instanceof Error ? e.message : "");
        setSglangOff(false);
      }
    } finally {
      if (!silent) setSglangLoading(false);
    }
  }, []);

  React.useEffect(() => {
    void refreshStatus();
    void refreshSglang(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 集群负载静默轮询（v1/loads 读 SHM 快照）。
  // → usePoller（ops tab 激活；切走即停 + 可见性
  // 内置——原「rc-tabs 保活切走也续」的每 1s 常驻开销由此消除）。
  // 一刀切 1s→5s（省 5M 行拨号）。
  // 改自适应节奏（getter 档）——14.17 的 5s 恒定档
  // 被验收实测打回「刷新很慢几乎不刷」：负载仪表要的是活性，省拨号
  // 靠空闲降档而非恒定降速。活跃 1s / 空闲 15s（refreshSglang 内
  // sgCadenceRef 按数据指纹切档）。
  usePoller({
    fn: () => void refreshSglang(true),
    intervalMs: () => sgCadenceRef.current,
    active: opsActive,
    minPokeMs: 800,
  });

  // 切 Tab 回来时（refreshTick 变化）重取——rc-tabs 保活不会重跑挂载 effect。
  React.useEffect(() => {
    if (!refreshTick) return;
    void refreshStatus();
    void refreshSglang(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refreshTick]);

  // 集群版本：ops tab 激活时取一次（后端 10min 缓存，无轮询必要）。
  React.useEffect(() => {
    if (opsActive) void refreshClusterInfo();
  }, [opsActive, refreshClusterInfo]);

  const statusEntries = React.useMemo(
    () =>
      status && typeof status === "object"
        ? Object.entries(status as Record<string, unknown>)
        : [],
    [status],
  );

  return (
    <div style={{ display: "grid", gap: 16 }}>
      {/* ：多运行时卡从运维页移除——静态 runtime
 清单硬编码不全 + 位置错。运行时管理归团队管理：每个 Worker/Manager 卡
 直接显示自己的 runtime·version（Worker 卡 / Manager 表本轮加列）。 */}
      {/* 集群状态 */}
      <div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 10,
          }}
        >
          <span style={{ fontWeight: 700, fontSize: 15 }}>集群状态</span>
          <WbTooltip title={tr("Controller /api/v1/status（L1 视图，dashboard cluster-status 同源）")}>
            <span style={{ color: t.textSecondary, cursor: "help", fontSize: 12 }}>ⓘ</span>
          </WbTooltip>
          <div style={{ flex: 1 }} />
          <WbTooltip title="刷新">
            <antd.Button
              type="text"
              size="small"
              icon={<ReloadIcon />}
              loading={statusLoading}
              onClick={() => {
                void refreshStatus();
                void refreshClusterInfo();
              }}
            />
          </WbTooltip>
        </div>
        {statusEntries.length === 0 && !clusterInfo ? (
          <antd.Empty
            description={statusLoading ? tr("加载中…") : tr("暂无状态数据")}
            image={antd.Empty.PRESENTED_IMAGE_SIMPLE}
          />
        ) : (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))",
              gap: 10,
            }}
          >
            {clusterInfo ? (
              <>
                <VersionStatCard
                  label={tr("AgentTeams 版本")}
                  value={clusterInfo.agentteams_version}
                  t={{ border: t.border, cardBg: t.cardBg, textSecondary: t.textSecondary }}
                />
                <VersionStatCard
                  label={tr("Higress 版本")}
                  value={clusterInfo.higress_version}
                  sub={
                    clusterInfo.higress_version_source
                      ? tr("来源：{s}", { s: clusterInfo.higress_version_source === "file" ? "集群容器配置" : "集群容器环境变量" })
                      : clusterInfo.higress_version_error
                        ? tr("探测失败")
                        : null
                  }
                  t={{ border: t.border, cardBg: t.cardBg, textSecondary: t.textSecondary }}
                />
              </>
            ) : null}
            {statusEntries.map(([key, value]) => {
              const display =
                value === null || value === undefined
                  ? "—"
                  : typeof value === "object"
                    ? JSON.stringify(value)
                    : String(value);
              return (
                <div
                  key={key}
                  style={{
                    padding: "10px 12px",
                    borderRadius: 8,
                    border: `1px solid ${t.border}`,
                    background: t.cardBg,
                  }}
                >
                  <div style={{ fontSize: 11, color: t.textSecondary }}>
                    {key}
                  </div>
                  <div
                    style={{
                      fontSize: 13,
                      fontWeight: 600,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                    title={display}
                  >
                    {display}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

 {/* （14.17 「运维页面不需要放模型网关路由，
 把模型页面做好就可以」）：路由目录卡整块移除——模型页（ModelsTab）
 已有同款「模型网关配置」（提供商/路由/alias 表，功能超集），运维页
 重复视图删除。 */}

      {/* 集群负载（可选模块，L1 专属——未启用时后端 404，不渲染） */}
      {!sglangOff ? (
        <div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              marginBottom: 10,
              flexWrap: "wrap",
            }}
          >
            <span style={{ fontWeight: 700, fontSize: 15 }}>
              集群负载
            </span>
            {/* 副标=检查节奏 + 刷新脉冲（14.34）——每收到一帧快照亮一次
  （remount key=sglangLocalAt 重放动画）：空闲数值不变时也能看出
  「正在刷新」。取代 14.33 恒显 0 的「快照 N 秒前」age 文字（用户
  点名删）与 14.26 的错误标注「数据快照 ~15s」（参数单位误读）。 */}
            <span style={{ fontSize: 11, color: t.textSecondary }}>
              {tr("自动刷新（活跃 1s / 稳定 5s）")}
            </span>
            {sglang ? (
              <span
                key={sglangLocalAt}
                title={tr("每收到一帧负载快照亮一次——正在实时刷新")}
                style={{
                  display: "inline-block",
                  width: 8,
                  height: 8,
                  borderRadius: "50%",
                  background: "#52c41a",
                  animation: "wbSgTick 0.9s ease-out",
                }}
              />
            ) : null}
            <WbTooltip
              title={tr(
                "SGLang 每 DP rank 排队/运行/显存（可选模块——配置页开启并填 SGLang 地址）。卡片按数据变化自适应检查：负载在变 1s 一轮，稳定 5s 一轮。绿点每收到一帧快照亮一次=正在实时刷新。",
              )}
            >
              <span style={{ color: t.textSecondary, cursor: "help", fontSize: 12 }}>
                ⓘ
              </span>
            </WbTooltip>
            <div style={{ flex: 1 }} />
            <WbTooltip title="刷新">
              <antd.Button
                type="text"
                size="small"
                icon={<ReloadIcon />}
                loading={sglangLoading}
                onClick={() => void refreshSglang()}
              />
            </WbTooltip>
          </div>
          {sglangError ? (
            <antd.Alert
              type="error"
              showIcon
              message={sglangError}
              style={{ fontSize: 12 }}
            />
          ) : sglang ? (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
                gap: 10,
              }}
            >
              {sglang.ranks.length === 0 ? (
                <antd.Empty
                  description={tr("暂无负载数据")}
                  image={antd.Empty.PRESENTED_IMAGE_SIMPLE}
                />
              ) : (
                sglang.ranks.map((r) => {
                  const busy = r.num_running_reqs + r.num_waiting_reqs;
                  const usagePct = Math.round(r.token_usage * 100);
                  return (
                    <div
                      key={r.dp_rank}
                      style={{
                        padding: "10px 12px",
                        borderRadius: 8,
                        border: `1px solid ${t.border}`,
                        background: t.cardBg,
                        display: "grid",
                        gap: 4,
                      }}
                    >
                      <div
                        style={{
                          display: "flex",
                          justifyContent: "space-between",
                          alignItems: "center",
                        }}
                      >
                        <span style={{ fontSize: 12, fontWeight: 600 }}>
                          {sglang.accelerator || "GPU"} · DP {r.dp_rank}
                        </span>
                        <antd.Tag
                          color={busy === 0 ? "green" : r.num_waiting_reqs > 0 ? "orange" : "blue"}
                          style={{ margin: 0, fontSize: 11 }}
                        >
                          {busy === 0
                            ? tr("空闲")
                            : r.num_waiting_reqs > 0
                              ? `${r.num_waiting_reqs} ${tr("排队")}`
                              : `${r.num_running_reqs} ${tr("运行中")}`}
                        </antd.Tag>
                      </div>
                      <div style={{ display: "flex", gap: 12, fontSize: 12 }}>
                        <span>
                          {tr("运行")}{" "}
                          <b>
                            {r.num_running_reqs}
                            {r.max_running_requests > 0
                              ? `/${r.max_running_requests}`
                              : ""}
                          </b>
                        </span>
                        <span>
                          {tr("排队")} <b>{r.num_waiting_reqs}</b>
                        </span>
                        {/* 吞吐 0 值语义显形——
 上游 decode 窗口采样，0 ≠ 空闲（KV 仍在动时推理在跑）。
 0 显示「—」+ 悬停说明；活动判定交给下方 KV 绿点（自采样）。 */}
                        <span style={{ cursor: "help" }}
                          title={tr("Decode 窗口采样：上游 30s 无 decode 报 0。0 不代表空闲——看下方 KV 绿点（最近一次轮询 KV 有变化 = 推理在跑）")}
                        >
                          {tr("吞吐")}{" "}
                          <b>
                            {r.gen_throughput > 0
                              ? `${r.gen_throughput.toFixed(1)} tok/s`
                              : "—"}
                          </b>
                        </span>
                      </div>
                      <div style={{ fontSize: 11, color: t.textSecondary }}>
                        {sgKvMovingRef.current.has(r.dp_rank) ? (
                          <span
                            style={{ color: "#52c41a", cursor: "help" }}
                            title={tr("最近一次轮询 KV 占用有变化——推理在跑")}
                          >
                            ●{" "}
                          </span>
                        ) : null}
                        KV {r.num_used_tokens.toLocaleString()}
                        {r.pool_total_tokens > 0
                          ? `/${r.pool_total_tokens.toLocaleString()}`
                          : ""}{" "}
                        tokens · 命中 {Math.round(r.cache_hit_rate * 100)}%
                      </div>
                      {(r.mem_weight_gb > 0 || r.mem_kv_gb > 0) && (
                        <div style={{ fontSize: 11, color: t.textSecondary }}>
                          {tr("显存：权重 {a}G · KV {b}G · 图 {c}G", {
                            a: r.mem_weight_gb.toFixed(1),
                            b: r.mem_kv_gb.toFixed(1),
                            c: r.mem_graph_gb.toFixed(1),
                          })}
                        </div>
                      )}
                      {/* KV 池占用率 = token_usage（上面 KV used/pool 的百分比）——
 用户真机问「54% 是什么的 54%」：进度条无标签，补 "KV" 前缀 */}
                      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                        <span
                          style={{
                            fontSize: 11,
                            color: t.textSecondary,
                            flexShrink: 0,
                          }}
                        >
                          {tr("KV 占用")}
                        </span>
                        <antd.Progress
                          percent={usagePct}
                          size="small"
                          status={usagePct > 85 ? "exception" : "normal"}
                          format={() => `${usagePct}%`}
                        />
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          ) : (
            <antd.Skeleton active title={false} paragraph={{ rows: 2 }} />
          )}
          {sglang && sglang.ranks.length > 0 && (
            <div
              style={{
                fontSize: 11,
                color: t.textSecondary,
                marginTop: 8,
                display: "flex",
                gap: 12,
                flexWrap: "wrap",
              }}
            >
              {sglang.version && (
                <span>
                  {tr("SGLang {v} · 每 rank {n} 卡", {
                    v: sglang.version,
                    n: sglang.num_accelerators > 0 ? sglang.num_accelerators : "?",
                  })}
                </span>
              )}
              {sglangLocalAt > 0 && (
                <span>
                  {tr("更新于 {time}", {
                    time: formatTimeOfDay(sglangLocalAt),
                  })}
                </span>
              )}
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

/**
 * OpsLogPane——组件日志区（Controller Docker API 代理 + 15s 轮询 +
 * 错误过滤 + 自动滚动跟随 + 回到最新）。P6 自单体 OpsPanel 拆出，供
 * 集群管理域「日志」二级页（覆盖中+右两栏）；轮询门与 OpsOverview 同款。
 */
export function OpsLogPane({
  refreshTick = 0,
  active = false,
}: {
  refreshTick?: number;
  active?: boolean;
}) {
  const t = useThemeColors();
  const tr = useT();
  const [component, setComponent] = React.useState("controller");
  const [logs, setLogs] = React.useState<LogLine[]>([]);
  const [logsLoading, setLogsLoading] = React.useState(false);
  const [levelFilter, setLevelFilter] = React.useState<"all" | "error">("all");
  const [autoScroll, setAutoScroll] = React.useState(true);
  const logBoxRef = React.useRef<HTMLDivElement | null>(null);

  // P6：|| active——顶层「运维」tab 下线后旧门恒 false，集群域
  // 「日志」二级页显式传激活。
  const opsActive = useTabActive("ops") || active;
  const [logsUpdatedAt, setLogsUpdatedAt] = React.useState<number>(0);
  // 轮询已并入 usePoller（ops tab 激活门控 +
  // 失败退避内置：×2 至 120s 封顶、成功复位；静默失败保留上次内容）。
  // silent=true：后台轮询不闪 loading（手动刷新按钮走非 silent）。
  const refreshLogs = React.useCallback(async (comp: string, silent = false) => {
    if (!silent) setLogsLoading(true);
    try {
      const data = (await requestJson(
        `/agentteams-proxy/docker-logs/${encodeURIComponent(comp)}?tail=300`,
      )) as { lines?: LogLine[] };
      setLogs(data.lines || []);
      setLogsUpdatedAt(Date.now());
    } catch (e) {
      if (!silent) {
        // 手动刷新失败：显式报错并清屏（用户主动动作，需明确反馈）。
        antd.message.error(e instanceof Error ? e.message : tr("日志拉取失败"));
        setLogs([]);
      }
      // 静默失败：保留上次成功内容（不 setLogs([])）。
    } finally {
      if (!silent) setLogsLoading(false);
    }
    // tr 每次 render 都是新函数但行为稳定（纯查表），不入 deps——否则轮询 timer 被反复重建
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 组件日志轮询 → usePoller（ops tab 激活；
  // !document.hidden 由 hook 内置；失败退避由 hook 内置）。
  usePoller({
    fn: () => void refreshLogs(component, true),
    intervalMs: 15000,
    active: opsActive,
  });

  React.useEffect(() => {
    void refreshLogs(component);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 切 Tab 回来时（refreshTick 变化）重取——rc-tabs 保活不会重跑挂载 effect。
  React.useEffect(() => {
    if (!refreshTick) return;
    void refreshLogs(component);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refreshTick]);

  const visibleLogs = React.useMemo(
    () => (levelFilter === "all" ? logs : logs.filter((l) => l.level === "error")),
    [logs, levelFilter],
  );

  // 旧版展示改「最新在上」(14.10) 但跟随逻辑留了
  // scrollTop=scrollHeight（滚到最底=最旧）——语义打架，轮询把用户视口拽走。
  // 现按业界标准（kubectl/docker --follow/Grafana logs 同款语义，适配最新在上）：
  // ① 跟随 = 顶部跟随（autoScroll 时 scrollTop=0，最新行永远贴顶可见）；
  // ② 用户向下翻（看旧日志，>60px）→ 自动暂停跟随（不打断阅读）；
  // ③ 暂停且不在顶 → 浮动「↑ 回到最新」钮 → 点击 = 回顶 + 恢复跟随。
  const [awayFromTop, setAwayFromTop] = React.useState(false);
  const onLogScroll = React.useCallback(() => {
    const el = logBoxRef.current;
    if (!el) return;
    const away = el.scrollTop > 60;
    setAwayFromTop(away);
    if (away) setAutoScroll(false); // 翻旧日志 = 自动暂停跟随（不打断阅读）
  }, []);
  const jumpToLatest = React.useCallback(() => {
    const el = logBoxRef.current;
    if (el) el.scrollTop = 0;
    setAwayFromTop(false);
    setAutoScroll(true);
  }, []);
  React.useEffect(() => {
    const el = logBoxRef.current;
    if (autoScroll && el) {
      el.scrollTop = 0;
      setAwayFromTop(false);
    }
  }, [visibleLogs, autoScroll]);

  return (
    <div>
      {/* 组件日志 */}
      <div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 10,
            flexWrap: "wrap",
          }}
        >
          <span style={{ fontWeight: 700, fontSize: 15 }}>组件日志</span>
          <WbTooltip title={tr("经 Controller Docker API 代理拉容器日志（dashboard debug-log 同源；需要管理员 token）")}>
            <span style={{ color: t.textSecondary, cursor: "help", fontSize: 12 }}>ⓘ</span>
          </WbTooltip>
          <span
            style={{
              fontSize: 11,
              color: t.textSecondary,
              // 行项 min 宽护栏：本行固定项（标题+提示+Select 200+Segmented+
              // Switch+刷新钮）在 768 容器仅 ~5px 余量，瞬态（如 loading
              // 钮变宽）超 6px 即刷新钮折行、开关贴右缘，antd Switch 的
              // 预定位隐藏 label（ml:68/mr:-68 过渡定位）被推越视口右缘
              // （审计 ops@768 瞬态 TRUE，单格重跑不复现）。本提示是行内
              // 唯一可变宽项：允许收缩（min 120px + ellipsis）吸收瞬态，
              // 不折行稳定区从 ≥728 扩到 ≥638，以下折行行为不变。
              minWidth: 120,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
            }}
          >
            {tr("自动刷新 15 秒")}
            {logsUpdatedAt > 0 &&
              ` · ${tr("{n} 行 · 更新于 {time}", {
                n: logs.length,
                time: formatTimeOfDay(logsUpdatedAt),
              })}`}
          </span>
          <div style={{ flex: 1 }} />
          <antd.Select
            size="small"
            style={{ width: 200 }}
            value={component}
            onChange={(v: string) => {
              setComponent(v);
              void refreshLogs(v);
            }}
            options={COMPONENTS}
          />
          <antd.Segmented
            size="small"
            value={levelFilter}
            onChange={(v: ReactNS.Key | number) =>
              setLevelFilter(v as "all" | "error")
            }
            options={[
              { value: "all", label: tr("全部") },
              { value: "error", label: tr("仅错误") },
            ]}
          />
          <antd.Switch
            size="small"
            checked={autoScroll}
            onChange={setAutoScroll}
            checkedChildren={tr("自动滚动")}
            unCheckedChildren={tr("暂停")}
          />
          <WbTooltip title={tr("刷新日志")}>
            <antd.Button
              type="text"
              size="small"
              icon={<ReloadIcon />}
              loading={logsLoading}
              onClick={() => void refreshLogs(component)}
            />
          </WbTooltip>
        </div>
        <div style={{ position: "relative" }}>
          <div
            ref={logBoxRef}
            onScroll={onLogScroll}
            style={{
              height: 420,
              overflowY: "auto",
              borderRadius: 8,
              background: "#0d1117",
              padding: 10,
              fontFamily: "ui-monospace, SFMono-Regular, Consolas, monospace",
              fontSize: 12,
              lineHeight: 1.6,
            }}
          >
          {logsLoading && visibleLogs.length === 0 ? (
            <div style={{ color: "#8b949e" }}>{tr("加载日志中…")}</div>
          ) : visibleLogs.length === 0 ? (
            <div style={{ color: "#8b949e" }}>{tr("（无日志行）")}</div>
          ) : (
 /* 最新在最上——展示倒序（不
 改动状态数组本身；过滤/计数语义不变）。 */
            [...visibleLogs].reverse().map((l, i) => (
              <div key={i} style={{ color: l.level === "error" ? "#ff7b72" : "#c9d1d9" }}>
                {l.timestamp ? (
                  <span style={{ color: "#8b949e" }}>
                    {fmtLogTime(l.timestamp)}{" "}
                  </span>
                ) : null}
                {l.message}
              </div>
            ))
          )}
          </div>
          {/* 暂停跟随且用户在翻旧日志 → 浮动「回到最新」钮（业界日志跟随
 标准件；点击=回顶+恢复跟随）。 */}
          {!autoScroll && awayFromTop ? (
            <antd.Button
              size="small"
              type="primary"
              style={{
                position: "absolute",
                top: 14,
                right: 14,
                boxShadow: "0 2px 8px rgba(0,0,0,0.35)",
                zIndex: 1,
              }}
              onClick={jumpToLatest}
            >
              {tr("↑ 回到最新")}
            </antd.Button>
          ) : null}
        </div>
      </div>
    </div>
  );
}

